// Rendering for this feature. State changes are handled by app.js and the domain models.
function photoSlots(p){return`<div class="field"><span class="field-label">My photos · at least one</span><div class="photo-slots" id="profile-photos" tabindex="-1">${p.photos.map((src,i)=>`<div class="photo-slot"><img src="${esc(src)}" alt="Your photo ${i+1}"><button class="photo-remove" data-action="photo-remove" data-value="${i}" aria-label="Remove photo ${i+1}">${icon('close')}</button></div>`).join('')}${p.photos.length<3?`<label class="photo-slot photo-add"><input type="file" accept="${PhotoInput.accept}" ${modal?.photoPending?'disabled':''} data-photo-input aria-label="Add a photo">${icon('plus')}<span aria-live="polite">${modal?.photoPending?'Preparing…':'Add photo'}</span></label>`:''}</div>${fieldError('photos')}<p class="caption">${icon('lock')} Hidden until you and your date both say yes after meeting.</p></div>`;}
async function addPhoto(file){
  const owner=modal;if(owner?.type!=='onboarding'||owner.photoPending)return;
  if(owner.draft.photos.length>=3){toast('You can add up to 3 photos.');return;}
  captureProfileFields();owner.photoPending=true;renderModal();
  try{
    const photo=await PhotoInput.prepare(file);
    if(modal!==owner)return;
    captureProfileFields();owner.draft.photos=[...owner.draft.photos,photo];delete owner.errors.photos;persistDraft();
  }catch(error){if(modal===owner)toast(error.message);}
  finally{delete owner.photoPending;if(modal===owner)renderModal();}
}
function factChip(label,graphic,missing=false,step=0){return`<button class="fact-chip ${missing?'missing':''}" data-action="onboarding" data-profile-step="${step}">${icon(graphic)}${esc(label)}${missing?icon('plus'):''}</button>`;}
function answerTile(label,text,action,extra=''){return`<button class="answer-tile" data-action="${action}" ${extra}><span class="tile-label">${label}</span><span class="tile-text">${text}</span><span class="tile-edit" aria-hidden="true">${icon('edit')}</span></button>`;}
function profilePage(){
  const p=state.profile,bills=p.billPreferences.map(v=>esc(Dating.billChoices(p).find(c=>c.id===v)?.title||v)),days=state.availability.windows.length;
  const facts=[p.education?factChip(p.education,'flower'):factChip('Education','flower',true),p.energy?factChip(p.energy,'people',false,2):factChip('Energy','people',true,2),p.intent?factChip(p.intent,'heart',false,3):factChip('Intentions','heart',true,3),Number.isInteger(p.height)?factChip(p.height+' cm','mountain'):factChip('Height','mountain',true),p.drinking?factChip('Drinks: '+p.drinking.toLowerCase(),'coffee',false,2):factChip('Drinking','coffee',true,2),p.workout?factChip('Works out: '+p.workout.toLowerCase(),'heart',false,2):factChip('Workout','heart',true,2),factChip(p.interests.length?`Interests (${p.interests.length})`:'Interests','coffee',!p.interests.length,3),factChip(p.values.length?`Values (${p.values.length})`:'Values','spark',!p.values.length,3)].join('');
  return`<div class="profile-header"><span class="profile-photo-stack" aria-hidden="true"><span>${p.name?esc(p.name.charAt(0).toUpperCase()):icon('user')}</span></span><div class="profile-header-copy"><h1 class="page-title profile-name" tabindex="-1">${p.name?esc(p.name):'Your profile'}${p.verification==='verified-demo'?`<span class="verified-mark" aria-label="Verified in demo only">${icon('seal')}</span>`:p.complete?`<span class="verified-mark" aria-label="Profile complete, identity not verified">${icon('check')}</span>`:''}</h1><p>${p.age?esc(p.age)+' · ':''}${p.verification==='verified-demo'?'ID verified (demo)':'Your face stays a mystery'}</p></div></div>
${!p.complete?`<button class="complete-pill" data-action="onboarding">${icon('warning',true)}${state.drafts.profile?'Continue your profile':'Complete your profile'}</button>`:''}<div class="fact-chips" aria-label="Profile details">${facts}</div>
<section class="section"><h2>My photos</h2><div class="panel photos-panel"><div class="photo-strip">${p.photos.length?p.photos.map((src,i)=>`<img src="${esc(src)}" alt="Your photo ${i+1}">`).join(''):`<span class="photo-empty">${icon('plus')}</span>`}</div><div class="photos-foot"><p><strong>Hidden until it’s mutual.</strong> Tip: one clear, recent photo of your face.</p>${button('Edit','onboarding','primary','data-profile-step="0"','')}</div></div></section><section class="section"><h2>My answers</h2><div class="tile-grid">${answerTile('My vibe',p.energy||p.activity?`${esc(p.energy||'Energy not set')}<br>${esc(p.activity||'')}`:'Tell us your energy','onboarding','data-profile-step="2"')}${answerTile('My lifestyle',p.drinking||p.workout||p.familyPlans?[p.workout&&'Works out '+p.workout.toLowerCase(),p.drinking&&'Drinks '+p.drinking.toLowerCase(),p.familyPlans].filter(Boolean).map(esc).join('<br>'):'Drinking, workout, family','onboarding','data-profile-step="2"')}${answerTile('Faith & background',[p.religion,p.ethnicity].filter(v=>v&&v!=='Prefer not to say').map(esc).join('<br>')||'Private · optional','onboarding','data-profile-step="1"')}${answerTile('Bill comfort',bills.length?bills.join('<br>'):'Choose what feels fair','profile-bill')}${answerTile('Who I’d like to meet',state.savedPreferences?'A saved type you can reuse':'Explore your type','navigate','data-view="home"')}${answerTile('My record',`${state.record.dates} date${state.record.dates===1?'':'s'}<br>${state.record.noShows} no-shows<br>${state.record.lateCancels} late cancels`,'navigate','data-view="dates"')}${answerTile('When I’m free',days?`${days} day${days>1?'s':''} saved`:'Pick days & places','navigate','data-view="availability"')}</div></section><section class="section"><h2>My interests</h2><div class="tile-grid">${answerTile('Currently into',p.interests.length?p.interests.slice(0,3).map(esc).join(', ')+(p.interests.length>3?`, +${p.interests.length-3}`:''):'Add a few interests','onboarding','data-profile-step="3"')}${answerTile('What I value',p.values.length?p.values.slice(0,3).map(esc).join(', ')+(p.values.length>3?`, +${p.values.length-3}`:''):'Add your values','onboarding','data-profile-step="3"')}</div></section><button class="plus-banner" data-action="membership"><span><strong>blinddate<span>+</span></strong><span>${state.previewPlan?'Demo membership active':'See records before you meet · see plans'}</span></span>${icon('arrow')}</button><section class="section"><h2>Settings</h2><div class="group-card appearance-card"><div><span class="row-icon">${icon(state.theme==='dark'?'moon':'sun')}</span><strong>Theme</strong></div><div class="segmented" role="group" aria-label="Theme"><button data-action="theme" data-value="dark" aria-pressed="${state.theme==='dark'}" class="${state.theme==='dark'?'selected':''}">Dark</button><button data-action="theme" data-value="light" aria-pressed="${state.theme==='light'}" class="${state.theme==='light'?'selected':''}">Light</button></div></div><div class="group-card">${row(p.verification==='verified-demo'?'Verified (demo)':'Verify my identity',p.verification==='verified-demo'?'Your date sees a Verified badge':'ID and a selfie · free for everyone','seal','verify','','violet')}${row('Safety and privacy','Your face and full profile stay hidden','shield','safety','','mint')}${row('Edit my profile','Age, education, personality and values','edit','onboarding')}</div><button class="button secondary wide-pill" data-action="auth-log-out">Log out</button><button class="button wide-pill" data-action="reset">Reset prototype</button><p class="page-note">Profiles, drafts and current date discussions are stored in this browser. Partner replies and notifications are simulated.<br>blinddate prototype · v0.6</p></section>`;}


function membershipPage() {
  const annual=state.plan==='annual';
  return `${pageHeading('Meet blinddate+','More butterflies.<br><em>Less small talk.</em>','For when you’re ready for another first hello.')}<section class="panel membership-panel"><span class="category-icon violet">${icon('crown')}</span><h2>A little more possibility.</h2><div class="plan-switch segmented" role="group" aria-label="Billing interval"><button data-action="billing" data-value="monthly" aria-pressed="${!annual}" class="${!annual?'selected':''}">Monthly</button><button data-action="billing" data-value="annual" aria-pressed="${annual}" class="${annual?'selected':''}">Yearly</button></div><div class="price">C$${annual?'299.99':'29.99'}<span> / ${annual?'year':'month'}</span></div><p class="billing-description">${annual?'C$299.99 billed upfront each year.<br>Equivalent to C$25.00/month; about 17% less than 12 monthly payments.':'C$29.99 billed monthly.<br>Cancel renewal any time.'}</p><ul class="feature-list"><li>${icon('people')} Two arranged-date credits each month</li><li>${icon('star')} See ratings, reviews and show-up records before you meet (otherwise C$1.99 each)</li><li>${icon('spark')} Show people slightly outside your age and distance when there’s no one</li><li>${icon('shield')} Safety check-ins and verification stay free for everyone</li></ul>${state.previewPlan?`<p class="saved-status">✓ Demo membership active · no payment</p>${button('End demo membership','end-membership','secondary','','')}`:button('Preview '+(annual?'yearly':'monthly')+' plan','select-plan')}</section><p class="page-note">Your first introduction is C$0. CAD before tax. Meals and drinks separate. No automatic subscription or payments in this demo.</p>`;
}
